blocks.text:
SELECT name AS 'Student Name',
       gpa  AS 'Grade Point'
FROM students;

SELECT columns
FROM table
WHERE condition;

-- students older than 20
SELECT * FROM students
WHERE age > 20;

-- find a specific student
SELECT * FROM students
WHERE name = 'Alice';

-- multiple conditions
SELECT * FROM students
WHERE age > 20 AND gpa >= 3.70;

SELECT columns
FROM table
ORDER BY column ASC|DESC;

-- highest GPA first
SELECT * FROM students
ORDER BY gpa DESC;

-- alphabetical by name
SELECT * FROM students
ORDER BY name ASC;

-- combined with WHERE + LIMIT
SELECT * FROM students
WHERE age > 20
ORDER BY gpa DESC LIMIT 10;

UPDATE table
SET column1 = new_value
WHERE condition;

-- remove one student
DELETE FROM students
WHERE id = 2;

-- remove low-GPA records
DELETE FROM students
WHERE gpa < 3.60;

-- count all students
SELECT COUNT(*) FROM students;

-- average GPA
SELECT AVG(gpa) FROM students;

-- highest and lowest GPA
SELECT MAX(gpa), MIN(gpa)
FROM students;

-- group by + count
SELECT age, COUNT(*) AS total
FROM students
GROUP BY age;
